import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_min_tanh_kernel(const float* input, float* output, 
                                    int batch_size, int channels, 
                                    int height, int width) {
    int spatial_size = height * width;
    int total_positions = batch_size * spatial_size;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_positions) {
        int batch = idx / spatial_size;
        int spatial_idx = idx % spatial_size;
        int h = spatial_idx / width;
        int w = spatial_idx % width;

        float min_val = INFINITY;
        for (int c = 0; c < channels; c++) {
            int input_idx = batch * channels * spatial_size + 
                          c * spatial_size + 
                          h * width + w;
            min_val = fminf(min_val, input[input_idx]);
        }

        // Apply tanh twice
        float result = tanhf(tanhf(min_val));

        int output_idx = batch * spatial_size + h * width + w;
        output[output_idx] = result;
    }
}

torch::Tensor fused_min_tanh_cuda(torch::Tensor input) {
    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int channels = sizes[1];
    int height = sizes[2];
    int width = sizes[3];

    auto output = torch::zeros({batch_size, 1, height, width}, 
                             input.options());

    int total_positions = batch_size * height * width;
    int block_size = 256;
    int num_blocks = (total_positions + block_size - 1) / block_size;

    fused_min_tanh_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width
    );

    return output;
}
"""

fused_kernel_cpp = "torch::Tensor fused_min_tanh_cuda(torch::Tensor input);"

fused_min_tanh = load_inline(
    name="fused_min_tanh",
    cpp_sources=fused_kernel_cpp,
    cuda_sources=fused_kernel_source,
    functions=["fused_min_tanh_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.fused_op = fused_min_tanh

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_op.fused_min_tanh_cuda(x)
        return x
